const app=document.querySelector('#project-app'),key='dock-project-'+app.dataset.id;
if(app.dataset.kind==='notes'){app.innerHTML='<label for="notes" style="display:block;margin-bottom:12px">Your space to think</label><textarea id="notes" placeholder="Start with a little idea…" style="width:100%;min-height:350px;border:1px solid var(--line);border-radius:12px;padding:25px;color:var(--text);background:var(--panel);line-height:1.8;resize:vertical"></textarea><p id="saved" style="font-size:11px;color:var(--muted)">Saved automatically in this browser</p>';const n=app.querySelector('textarea');n.value=localStorage.getItem(key)||'';n.oninput=()=>{localStorage.setItem(key,n.value);document.querySelector('#saved').textContent='Saved just now'}}
if(app.dataset.kind==='timer'){let remaining=25*60,interval;app.innerHTML='<div style="background:var(--hover);padding:55px;border-radius:16px;text-align:center"><div id="clock" style="font-size:clamp(48px,12vw,80px);font-weight:600;letter-spacing:-3px;color:var(--accent)">25:00</div><p style="color:var(--muted)">One thing at a time.</p><div style="display:flex;justify-content:center;gap:12px;margin-top:25px"><button class="primary" id="start">Start focus</button><button class="secondary" id="reset">Reset</button></div><p id="message" role="status"></p></div>';const display=()=>document.querySelector('#clock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');document.querySelector('#start').onclick=()=>{if(interval){clearInterval(interval);interval=null;document.querySelector('#start').textContent='Resume';return}if(remaining===0)remaining=1500;document.querySelector('#start').textContent='Pause';interval=setInterval(()=>{remaining--;display();if(remaining<=0){clearInterval(interval);interval=null;document.querySelector('#message').textContent='A little progress. Time for a break.';document.querySelector('#start').textContent='Start again'}},1000)};document.querySelector('#reset').onclick=()=>{clearInterval(interval);interval=null;remaining=1500;display();document.querySelector('#start').textContent='Start focus';document.querySelector('#message').textContent=''}}
if(app.dataset.kind==='colors'){app.innerHTML='<p>Build a palette for your next project.</p><div style="display:flex;gap:10px" id="palette"></div><button class="primary" id="shuffle" style="margin-top:25px">Generate a palette ↻</button>';const draw=()=>{const hue=Math.floor(Math.random()*360);document.querySelector('#palette').innerHTML=Array.from({length:5},(_,i)=>{const c=`hsl(${(hue+i*22)%360} 32% ${50+i*8}%)`;return `<div style="flex:1;height:200px;border-radius:9px;background:${c};display:flex;align-items:flex-end;padding:15px"><span style="font-size:11px">${c}</span></div>`}).join('')};draw();document.querySelector('#shuffle').onclick=draw}
